 556	\begin{definition}[State space of a linear register]\label{def:lin-reg}
 557		\uses{def:complementary}
 558		For a set $V$, we write $\C^V$ for the complex vector space of dimension
 559		$|V|$, endowed with the canonical orthonormal basis
 560		$\{\ket{x}\}_{x \in V}$. A \emph{quantum state on $V$} is a unit vector
 561		$\ket{\psi}_V \in \C^V$. If $V = \bigoplus_{i=1}^k V_i$ is a direct sum of
 562		subspaces over $\F$, then $\C^V$ is identified with
 563		$\bigotimes_{i=1}^k \C^{V_i}$ by identifying
 564		$\ket{x_1 \oplus \dots \oplus x_k}$ with
 565		$\ket{x_1} \ot \dots \ot \ket{x_k}$. In particular, a basis $\{e_i\}$ of
 566		$V$ yields the decomposition $V = \bigoplus_{i=1}^k (\F e_i)$ and hence
 567		$\C^V = \bigotimes_{i=1}^k \C^{|\F|}$; the factors $\C^{|\F|}$ are called
 568		the \emph{qudits} of $\C^V$.
 569	\end{definition}
 570	
 571	\begin{definition}[EPR state]\label{def:EPR}
 572		\uses{def:lin-reg}
 573		For a linear space $V$ over a finite field $\F$, the \emph{EPR state} on
 574		$\C^V \ot \C^V$ is
 575		\[
 576			\ket{\mathrm{EPR}}_V
 577			= \frac{1}{\sqrt{|V|}} \sum_{x \in V} \ket{x} \ot \ket{x}\;.
 578		\]
 579		We write $\ket{\mathrm{EPR}_q}$ for $\ket{\mathrm{EPR}}_{\F_q}$ and
 580		$\ket{\mathrm{EPR}}$ for $\ket{\mathrm{EPR}_2}$.
 581	\end{definition}
