 644		\uses{def:generalized-pauli, def:subfield-trace, def:dot-product-orthogonal}
 645		Let $q = p^k$, let $n \ge 1$ be an integer, and let $W \in \{X, Z\}$.
 646		\begin{enumerate}
 647			\item For all $a, a' \in \F_q$ and $b \in \F_p$,
 648			      \begin{equation}\label{eq:pauli-product-power}
 649				      \tau^W(a)\, \tau^W(a') = \tau^W(a + a')
 650				      \qquad \text{and} \qquad
 651				      \bigl(\tau^W(a)\bigr)^b = \tau^W(ab)\;;
 652			      \end{equation}
 653			      in particular $\bigl(\tau^W(a)\bigr)^p = \Id$. By the explicit
 654			      definitions each $\tau^W(a)$ is unitary, and its eigenvalues are
 655			      $p$-th roots of unity.
 656			\item For all $a, b \in \F_q^n$,
 657			      % Paper equation label kept on the display it names.
 658			      \begin{equation}\label{eq:twisted-fq}
 659				      \tau^X(a)\, \tau^Z(b)
 660				      = \omega^{-\tr(a \cdot b)}\, \tau^Z(b)\, \tau^X(a)\;,
 661			      \end{equation}
 662			      where $a \cdot b = \sum_{i=1}^n a_i b_i \in \F_q$. The case
 663			      $q = p$, $n = 1$ reads
 664			      \begin{equation}\label{eq:twisted-fp}
 665				      \sigma^X(a)\, \sigma^Z(b)
 666				      = \omega^{-ab}\, \sigma^Z(b)\, \sigma^X(a)
 667				      \qquad \text{for all } a, b \in \F_p\;.
 668			      \end{equation}
 669		\end{enumerate}
 670	\end{lemma}
 671	\begin{proof}
 672		\uses{def:generalized-pauli, def:subfield-trace}
 673		All identities are verified on computational basis states. For the product
 674		relations with $W = X$, shifting twice by $a'$ and $a$ equals shifting by
 675		$a + a'$; with $W = Z$, the phases $\omega^{\tr(aj)}\omega^{\tr(a'j)}$
 676		combine by $\F_q$-linearity of the trace, and the power relation follows by
 677		iterating. For the scalar twisted commutation,
 678		$\tau^X(a)\tau^Z(b)\ket{j} = \omega^{\tr(bj)}\ket{j + a}$, while
 679		$\tau^Z(b)\tau^X(a)\ket{j} = \omega^{\tr(b(j+a))}\ket{j + a} =
 680		\omega^{\tr(ab)}\,\omega^{\tr(bj)}\ket{j + a}$. The multi-qudit relation
 681		follows by applying the scalar relation factor by factor and summing the
 682		exponents, using $\tr(a \cdot b) = \sum_i \tr(a_i b_i)$. For $q = p$ the
 683		trace is the identity map, which gives \eqref{eq:twisted-fp}.
 684	\end{proof}
